package com.bankingax.task.b02;
import com.bankingax.core.api.DomainException; import com.bankingax.core.verification.*; import java.time.*; import java.util.*; import org.springframework.stereotype.Service;
/** Fake-only B-02: rule result first, immutable command only after consent/signature/OTP. */
@Service public class B02Service {
 private final VerificationPort otp; private final B02MockCloseCommand closeCommand; private final Map<Long,A> accounts=new HashMap<>(); private final Map<String,R> done=new HashMap<>();
 public B02Service(VerificationPort otp,B02MockCloseCommand closeCommand){this.otp=otp;this.closeCommand=closeCommand;accounts.put(3001L,new A(3001,1,LocalDate.of(2023,1,1),false,false,"ACTIVE",0));}
 public synchronized P prepare(long customer,long account,boolean waive,Boolean taxed){A a=owned(customer,account); return judge(a,waive,taxed);}
 public synchronized VerificationIssue issue(long customer,long account,int version,boolean consent,boolean signed,String phone){A a=owned(customer,account);if(!a.status.equals("ACTIVE")||a.version!=version)throw new DomainException("STATE_CHANGED","Account state changed.");if(!consent||!signed)throw new DomainException("CONSENT_OR_SIGNATURE_REQUIRED","Consent and mock signature are required.");return otp.issue(new VerificationIssueCommand(customer,account,VerificationAction.B02_EXECUTE,version,phone));}
 public VerificationBinding verify(long customer,String challenge,String code){return otp.verify(new VerificationVerifyCommand(customer,challenge,code));}
 public synchronized R execute(C c){A a=owned(c.customer,c.account);R old=done.get(c.requestId);if(old!=null){if(!old.same(c))throw new DomainException("DUPLICATE_REQUEST_CONFLICT","requestId was reused.");return old;} if(!a.status.equals("ACTIVE")||a.version!=c.version)throw new DomainException("STATE_CHANGED","Account state changed.");P p=judge(a,c.waive,c.taxed);if(p.manual)throw new DomainException("MANUAL_REVIEW_REQUIRED","Branch consultation is required.");if("DOCUMENT_REQUIRED".equals(p.rate))throw new DomainException("REQUIRED_DOCUMENT_MISSING","Tax certificate confirmation or waiver is required.");otp.consume(new VerificationConsumeCommand(c.binding,c.customer,c.account,VerificationAction.B02_EXECUTE,c.version));closeCommand.close(a.id);a.status="CLOSED";a.version++;R r=new R(c.requestId,c.customer,c.account,"CLOSED",p.rate,p.rule,c);done.put(c.requestId,r);return r;}
 private A owned(long c,long id){A a=accounts.get(id);if(a==null)throw new DomainException("NOT_FOUND","Housing savings account was not found.");if(a.customer!=c)throw new DomainException("FORBIDDEN","Customer ownership cannot be verified.");return a;}
 private P judge(A a,boolean waive,Boolean taxed){long months=java.time.temporal.ChronoUnit.MONTHS.between(a.joined,LocalDate.now());if(months<=1)return new P("NO_INTEREST","B2-R1",false);if(waive)return new P("BASE_RATE","B2-R3",false);if(months<24&&!a.won)return new P("BASE_RATE","B2-R2",false);if(taxed==null)return new P("DOCUMENT_REQUIRED","B2-R6",false);if(taxed)return new P("MANUAL_REVIEW","B2-R5",true);return new P("PREFERRED_RATE","B2-R4",false);}
 private static class A{long id,customer;LocalDate joined;boolean won,converted;String status;int version;A(long i,long c,LocalDate j,boolean w,boolean x,String s,int v){id=i;customer=c;joined=j;won=w;converted=x;status=s;version=v;}}
 public record P(String rate,String rule,boolean manual){} public record C(String requestId,long customer,long account,int version,boolean waive,Boolean taxed,String binding){} public record R(String requestId,long customer,long account,String status,String rate,String rule,C command){boolean same(C c){return command.equals(c);}}
}
